SET TIME ZONE 'UTC';
SELECT r.sku,coalesce(sum(v.receita_mercadoria_pos_devolucao) FILTER(WHERE v.elegivel AND (p.data_pedido AT TIME ZONE 'America/Sao_Paulo')::date BETWEEN DATE '2023-01-01' AND DATE '2025-12-31'),0) receita_mercadoria_pos_devolucao,coalesce(sum(v.custo_mercadoria_mantida) FILTER(WHERE v.elegivel AND (p.data_pedido AT TIME ZONE 'America/Sao_Paulo')::date BETWEEN DATE '2023-01-01' AND DATE '2025-12-31'),0) custo_mercadoria_mantida,coalesce(sum(v.margem_mercadoria) FILTER(WHERE v.elegivel AND (p.data_pedido AT TIME ZONE 'America/Sao_Paulo')::date BETWEEN DATE '2023-01-01' AND DATE '2025-12-31'),0) margem_mercadoria,count(*) FILTER(WHERE v.elegivel AND (p.data_pedido AT TIME ZONE 'America/Sao_Paulo')::date BETWEEN DATE '2023-01-01' AND DATE '2025-12-31' AND v.preco_unitario-v.desconto_unitario-v.custo_unitario<0) quantidade_linhas_margem_unitaria_negativa,coalesce(sum(v.quantidade*(v.preco_unitario-v.desconto_unitario-v.custo_unitario)) FILTER(WHERE v.elegivel AND (p.data_pedido AT TIME ZONE 'America/Sao_Paulo')::date BETWEEN DATE '2023-01-01' AND DATE '2025-12-31' AND v.preco_unitario-v.desconto_unitario-v.custo_unitario<0),0) valor_margem_original_negativa FROM produtos r LEFT JOIN vw_itens_venda v USING(produto_id) LEFT JOIN pedidos p ON p.pedido_id=v.pedido_id GROUP BY r.produto_id,r.sku ORDER BY margem_mercadoria DESC,r.sku;
